        self.tweets[user_id].append((self.time, tweet_id))
        self.time += 1

    def getNewsFeed(self, user_id: int) -> List[int]:
        pq = []  # (-time, tweetId, user, idx)
        for u in self.follows[user_id] | {user_id}:
            t = self.tweets[u]
            if t:
                i = len(t) - 1
                heapq.heappush(pq, (-t[i][0], t[i][1], u, i))
        feed = []
        while pq and len(feed) < 10:
            _, tid, u, i = heapq.heappop(pq)
            feed.append(tid)
            if i > 0:
                tm, nid = self.tweets[u][i - 1]
                heapq.heappush(pq, (-tm, nid, u, i - 1))
        return feed

    def follow(self, follower_id: int, followee_id: int) -> None:
        if follower_id != followee_id:
            self.follows[follower_id].add(followee_id)

    def unfollow(self, follower_id: int, followee_id: int) -> None:
        self.follows[follower_id].discard(followee_id)
