        used = [False] * len(nums)

        def go() -> None:
            if len(path) == len(nums):
                res.append(path[:])
                return
            for i, x in enumerate(nums):
                if used[i]:
                    continue
                used[i] = True
                path.append(x)
                go()
                used[i] = False
                path.pop()

