class Solution:
    def partition(self, s: str) -> List[List[str]]:
        res, path = [], []

        def is_pal(i: int, j: int) -> bool:
            while i < j:
                if s[i] != s[j]:
                    return False
                i, j = i + 1, j - 1
            return True

        def go(start: int) -> None:
            if start == len(s):
                res.append(path[:])
                return
            for end in range(start, len(s)):
                if not is_pal(start, end):
                    continue
                path.append(s[start:end + 1])
                go(end + 1)
                path.pop()

        go(0)
        return res
```

